command -v paraview || true
ls /opt/conda/bin | rg 'pv|vtk|ttk' | head -50
python - <<'PY'
try:
 import vtk
 print('vtk',vtk.VTK_VERSION)
except Exception as e: print(e)
try:
 import ttk
 print('ttk module yes')
except Exception as e: print('ttk err',e)
PY"

